[4542] = { en = "Message to Freewind Post", tier = 2,
  t = "Bericht voor Freewind Post",
  d = "Dappere reiziger, de centauren vallen dit gebied steeds vaker aan. Freewind Post moet meteen weten dat ze ons opnieuw lastigvallen! Zoek Cliffwatcher Longhorn in Freewind Post, in het zuidoosten, en geef hem dit dringende bericht.$b$bPas op en blijf uit de buurt van de Grimtotem Clan hier vlakbij... ze doen de laatste tijd vreemd tegen ons.$b$b$b",
  o = "Breng de Urgent Message naar Cliffwatcher Longhorn in Freewind Post.",
  p = "Wat wil je, $c? Een dringend bericht - voor mij?$b",
  c = "Nog meer slecht nieuws! Deze centauren gaan te ver! Ze hebben een van mijn karavanen met voorraden overvallen en de hele groep afgeslacht. Dit is schandalig, en het blijft niet ongestraft!$b",
  g = { {"vallen aan", "attack (aanvallen)"}, {"lastigvallen", "harass, bother"}, {"dringende", "urgent (dringend)"}, {"Pas op", "be careful (oppassen)"}, {"uit de buurt", "away from, out of reach"}, {"vlakbij", "close by"}, {"karavanen", "caravans (karavaan)"}, {"voorraden", "supplies (voorraad)"}, {"overvallen", "raided (overvallen)"}, {"afgeslacht", "slaughtered (afslachten)"}, {"schandalig", "outrageous, shameful"}, {"ongestraft", "unpunished"} },
},

[4841] = { en = "Pacify the Centaur", tier = 2,
  t = "Bedwing de centauren",
  d = "$N, ik smeek je om op deze centauren te jagen. Ze zullen de woede van onze wraak voelen. Val het kamp van de centauren ten noorden van Freewind Post aan! Laat woede je hand leiden!$b",
  o = "Dood 12 Galak Scouts, 10 Galak Wranglers en 6 Galak Windchasers, en ga dan terug naar Cliffwatcher Longhorn in Freewind Post.",
  p = "Kom op, $N, ik weet dat je je deel nog niet hebt gedood. Jaag op ze, en ik geef je een beloning als dank.$b",
