},

[1149] = { en = "Test of Faith", tier = 2,
  t = "Proef van geloof",
  d = "Dus je hebt mij gezocht, of misschien brengt het lot je bij mij? Het maakt niet uit. Je bent nu hier, en dus begint je reis opnieuw.$B$BEen wezen bestaat uit veel kanten: de geest, het lichaam, het verstand. Sommige kun je meten met de tradities van een cultuur. Van andere kunnen we alleen hopen dat ze in onszelf bestaan. Als je het goed vindt, test ik een paar van die kanten in jou.$B$BAls je slaagt, word je sterker. Als je zakt, dan zul je begrijpen hoe groot de Nether is.$B$BDe eerste is een Proef van geloof.",
  o = "Als je geloof hebt, spring dan van de planken boven Thousand Needles.",
  p = "Geloof. Het is veel belangrijker dan sommigen beseffen.$B$BSoms maakt het niet uit wat je gelooft. Het is gewoon belangrijk dat je ergens in gelooft.",
  c = "Pas als we tegenslag krijgen die we niet zagen aankomen, gaan we zien hoe sterk onze geest is. Je hebt de sprong in het diepe gewaagd, ook al had je geen garantie dat je het zou overleven. Je verstand staat open, en je geest is klaar voor wat komt.$B$BAls je wilt, is je volgende proef klaar.",
  g = { {"Proef", "test, trial"}, {"geloof", "faith"}, {"het lot", "destiny, fate"}, {"wezen", "being, creature"}, {"kanten", "sides, facets (kant)"}, {"verstand", "mind, intellect"}, {"meten", "measure"}, {"slaagt", "pass, succeed (slagen)"}, {"zakt", "fail (an exam) (zakken)"}, {"beseffen", "realize"}, {"tegenslag", "adversity, setback"}, {"de sprong in het diepe gewaagd", "took the leap of faith (een sprong wagen)"}, {"garantie", "guarantee"}, {"overleven", "survive"} },
},

[4821] = { en = "Alien Egg", tier = 2,
  t = "Het vreemde ei",
  d = "Er gaat een gerucht over een vreemd ei hier in Thousand Needles. Wie dit ei gezien heeft, kon niet eens dichtbij genoeg komen om het goed te bekijken. Slangen bewaken het ei alsof het een van hun eigen eieren is.$B$BIk wil dat je dit vreemde ei zoekt en het naar mij brengt, zodat ik het kan onderzoeken. Volgens de berichten ligt het ei in een slangenhol, maar er zijn een paar slangenholen aan de voet van de rotswanden, ten zuiden en ten noordoosten van Freewind Post.",
  o = "Breng het Alien Egg terug naar Hagar Lightninghoof in Freewind Post.",
  p = "Ik moet meer weten over dit geheimzinnige ei. Wie weet wat eruit komt.",
  c = "Ja, eindelijk... het geheimzinnige ei is eindelijk bij me gebracht. Laat me dit eens beter bekijken... Wat..! Wat is dit..?$b",
  g = { {"gerucht", "rumour"}, {"vreemd", "strange, alien"}, {"bewaken", "guard"}, {"onderzoeken", "examine, investigate"}, {"Volgens de berichten", "according to the reports"}, {"slangenhol", "serpent den"}, {"slangenholen", "serpent dens"}, {"aan de voet van", "at the base of"}, {"rotswanden", "cliff walls (rotswand)"}, {"geheimzinnige", "mysterious (geheimzinnig)"}, {"wat eruit komt", "what will hatch from it (uitkomen)"} },
},

[4865] = { en = "Serpent Wild", tier = 2,
  t = "Wilde slang",
  d = "Als ik het niet met mijn eigen ogen had gezien, had ik nooit geloofd dat het waar was. De wraak is naar Thousand Needles gekomen!$B$B<Hagar veegt over zijn voorhoofd.>$B$B$N, je moet snel handelen! Ga nu en zoek Motega Firemane; hij is in Whitereach Post, vlak ten noordwesten van Freewind Post langs de weg. Hij weet wat er moet gebeuren!",
  o = "Vertel Motega Firemane wat je hebt gevonden.",
  c = "Wraak! Dus de legende van Arikara is waar. Dit is echt een probleem dat meteen opgelost moet worden.",
  g = { {"met mijn eigen ogen", "with my own eyes"}, {"geloofd", "believed (geloven)"}, {"wraak", "vengeance"}, {"veegt", "wipes (vegen)"}, {"voorhoofd", "forehead, brow"}, {"handelen", "act"}, {"vlak", "just, right (vlak bij)"}, {"langs de weg", "along the road"}, {"legende", "legend"}, {"opgelost", "solved, resolved (oplossen)"} },
},

[5062] = { en = "Sacred Fire", tier = 2,
  t = "Het heilige vuur",
  d = "Arikara is een dodelijk wezen dat snel aangepakt moet worden. Om op haar te jagen moet je het heilige vuur van het leven aansteken - dat roept Arikara op.$B$BGa nu en oogst de zeldzame Incendia agave-plant. Als je genoeg agave hebt geoogst, ga dan om raad vragen bij Magatha Grimtotem op Elder Rise in Thunder Bluff. Ze is een machtige sjamaan die de agave-plant kan betoveren tot een poeder dat het vuur aansteekt.$B$BReis naar het noordoosten, naar de Boiling Pool, en verzamel Incendia Agave.",
  o = "Verzamel 10 bossen Incendia Agave en vraag daarna raad aan Magatha Grimtotem op Elder Rise in Thunder Bluff.",
  p = "Dus Motega Firemane stuurt bericht over Arikara... nou, dat is ernstig nieuws.$B$B<Magatha kijkt om zich heen.>$B$BArikara is een dodelijk wezen. Ze is alleen geboren om wraak te nemen op wie vreselijke daden heeft gepleegd.$B$B<Magatha glimlacht.>",
  c = "Goed, je hebt de nodige hoeveelheid Incendia agave verzameld. Dit zeldzame kruid vind je alleen in Thousand Needles. Het helpt om het slapende heilige vuur van het leven aan te steken.$B$B<Magatha begint de Incendia agave te betoveren.>",
  g = { {"heilige", "sacred (heilig)"}, {"dodelijk", "deadly"}, {"aangepakt", "dealt with (aanpakken)"}, {"aansteken", "light, kindle"}, {"roept op", "summons (oproepen)"}, {"oogst", "harvest (oogsten)"}, {"zeldzame", "rare (zeldzaam)"}, {"om raad vragen", "ask for advice, seek council"}, {"betoveren", "enchant"}, {"bossen", "bunches, bushels (bos)"}, {"ernstig", "serious, grave"}, {"wraak te nemen op", "take revenge on (wraak nemen)"}, {"daden", "deeds (daad)"}, {"gepleegd", "committed (plegen)"}, {"hoeveelheid", "amount"}, {"kruid", "herb"} },
},

[4881] = { en = "Assassination Plot", tier = 2,
  t = "Het moordplan",
  d = "De tauren Kanati Greycloud is brutaal: hij heeft een jachtkamp opgezet in Thousand Needles. We moeten hem doden om van dit jachtkamp af te komen, en van iedereen die hem misschien volgt. We komen samen bij de kleine post ten zuidwesten van de Great Lift.$b",
  o = "Waarschuw Kanati Greycloud in Whitereach Post voor het plan om hem te doden.",
  c = "Ze komen om mij te doden? Ik zal ze laten zien hoe een tauren vecht!",
  g = { {"moordplan", "assassination plot"}, {"brutaal", "bold, cheeky"}, {"jachtkamp", "hunting camp"}, {"opgezet", "set up (opzetten)"}, {"af te komen", "get rid of (afkomen van)"}, {"komen samen", "converge, gather (samenkomen)"}, {"ten zuidwesten van", "southwest of"}, {"Waarschuw", "warn (waarschuwen)"} },
},

[4966] = { en = "Protect Kanati Greycloud", tier = 2,
  t = "Bescherm Kanati Greycloud",
  d = "Maar er zijn misschien meer centauren dan ik dacht. Ik vraag je, $n, om met mij te vechten tegen deze gemene moordenaars.",
  o = "Bescherm Kanati Greycloud tegen de aanval van de centauren.",
  c = "Bedankt voor je hulp, $n. Zonder jou had ik ze niet kunnen tegenhouden.",
  e = "Bescherm Kanati Greycloud",
  g = { {"Bescherm", "protect (beschermen)"}, {"gemene", "vile, nasty (gemeen)"}, {"moordenaars", "assassins, murderers (moordenaar)"}, {"aanval", "attack"}, {"tegenhouden", "hold off, stop"} },
},

[5064] = { en = "Grimtotem Spying", tier = 2,
  t = "De Grimtotem bespioneren",
  d = "$N, je hebt ons eerder goed geholpen, dus nu vertrouw ik je een belangrijke opdracht toe. De Grimtotem Clan is in het geheim iets van plan. De afgelopen weken zijn drie agenten van onbekende afkomst bij de Grimtotem op bezoek geweest. We hebben ontdekt dat er in Darkcloud Pinnacle aparte kisten staan met deze bewaakte berichten.$b$b$N, als je slaagt in deze gevaarlijke opdracht, beloon ik je daarvoor.$b",
  o = "Vind de drie Secret Notes in Darkcloud Pinnacle en neem ze mee.",
  p = "Heb je ontdekt wat de Grimtotem van plan zijn?",
  c = "Grote Geesttotem! Dit is echt ernstig nieuws. Ik moet een plan maken voor wat er ook maar kan komen.$b$b$N, zoals beloofd, hier is je beloning voor je dappere dienst.$b",
  g = { {"bespioneren", "spy on"}, {"vertrouw toe", "entrust (toevertrouwen)"}, {"opdracht", "mission, task"}, {"in het geheim", "in secret"}, {"van plan", "up to, planning"}, {"agenten", "agents (agent)"}, {"onbekende afkomst", "unknown origin"}, {"ontdekt", "discovered (ontdekken)"}, {"aparte", "separate (apart)"}, {"kisten", "chests (kist)"}, {"bewaakte", "guarded (bewaken)"}, {"Geesttotem", "spirit totem"}, {"dienst", "service"} },
},

[5088] = { en = "Arikara", tier = 2,
  t = "Arikara",
  d = "Neem dit verfijnde en gezuiverde Incendia-poeder mee naar Thousand Needles en gooi het op het heilige vuur van het leven. Het vuur is in Darkcloud Pinnacle, op een losstaande naald waar ze hun doden begraven.$B$BDe betovering die ik in het Incendia-poeder heb geweven, roept Arikara naar je toe, $N.$B$BIk ben bang dat ze Cairne Bloodhoof besluipt; er is te veel veranderd in de overlevering van de tauren, en ik vrees dat dit Arikara boos heeft gemaakt. Wees snel, voordat alles verloren is, $c!",
  o = "Dood Arikara. Breng haar resten en het Incendia-poeder naar Motega Firemane in Whitereach Post als bewijs van je daad.",
  p = "Heb je de wrede slang Arikara gedood, $N?",
  c = "Dit klopt niet. Waarom zou Arikara achter Cairne Bloodhoof aan zitten? Magatha kan zich niet vergissen, ze is onze machtigste sjamaan.$B$B<Motega schudt zijn hoofd.>$B$BHoe dan ook, je grote daad voor de Horde zal niet onopgemerkt blijven - kies alsjeblieft een van deze dingen als beloning voor je hulp.",
  e = "Steek het heilige vuur van het leven aan",
  g = { {"verfijnde", "refined (verfijnd)"}, {"gezuiverde", "purified (zuiveren)"}, {"losstaande", "isolated, freestanding (losstaand)"}, {"naald", "needle"}, {"begraven", "bury"}, {"betovering", "enchantment"}, {"geweven", "woven (weven)"}, {"besluipt", "stalks (besluipen)"}, {"overlevering", "lore, tradition"}, {"vrees", "fear (vrezen)"}, {"resten", "remains (rest)"}, {"bewijs", "proof"}, {"wrede", "vicious, cruel (wreed)"}, {"vergissen", "be wrong, make a mistake (zich vergissen)"}, {"onopgemerkt", "unnoticed"} },
},

[4767] = { en = "Wind Rider", tier = 2,
  t = "Windrijder",
  d = "Ik heb de opdracht gekregen om meer wyverns te werven voor de meester-windrijders. Hun aantal groeit, en ik hoop zelf ooit windrijder te worden. Maar we kunnen niet genoeg wyverns trainen om de vraag bij te houden. Misschien kun jij me helpen, $N.$B$BIk wil dat je naar Highperch gaat om wyverneieren te verzamelen. Ga vanaf hier naar het noordwesten, langs de wanden van de kloof, naar een helling die je naar Highperch brengt. Wees voorzichtig: wyverns beschermen hun eieren heel goed, en ze zijn niet vriendelijk tegen indringers.",
  o = "Breng 10 Highperch Wyvern Eggs naar Elu in Freewind Post.",
  p = "$N, heb je de wyverneieren gevonden die ik zoek? Ik wil zo graag beginnen met mijn training als windrijder!",
  c = "Perfect! Met deze eieren hoop ik de volgende stap te zetten om windrijder te worden. Hier is iets als teken van mijn dank; moge goede jacht altijd op je schijnen, $C.",
  g = { {"windrijder", "wind rider"}, {"werven", "recruit"}, {"aantal", "number"}, {"ooit", "one day, ever"}, {"de vraag bij te houden", "keep up with the demand (bijhouden)"}, {"wyverneieren", "wyvern eggs"}, {"wanden", "walls (wand)"}, {"kloof", "canyon, gorge"}, {"helling", "slope, ramp"}, {"indringers", "intruders (indringer)"}, {"teken", "token, sign"}, {"moge", "may (wish form of mogen)"}, {"schijnen", "shine"} },
},

[4770] = { en = "Homeward Bound", tier = 2,
  t = "Op weg naar huis",
  d = "Help me alsjeblieft, $c! Ik verstop me al een tijdje hier in Highperch, en ik heb al dagen geen vriendelijk gezicht gezien. Ik kwam hier om de wyverns te bestuderen, en ik denk dat ik iets te dichtbij kwam. Ik werd weggejaagd bij een van de nesten, en daarna raakte ik verdwaald.$B$BIk moet terug naar Whitereach Post! Motega weet niet dat ik vermist ben, en hij wordt woedend als hij hoort dat ik in mijn eentje naar Highperch ben gegaan.$B$BWhitereach Post ligt vlak ten oosten van hier... breng me er alsjeblieft heen!",
  o = "Begeleid Pao'ka Swiftmountain uit Highperch en praat daarna met Motega Firemane in Whitereach Post.",
  c = "Wat!? Als ik had geweten dat Pao'ka Swiftmountain in Highperch ging rondneuzen, had ik hem aan een totem vastgeketend! Zijn vader wilde hem eigenlijk niet met mij mee laten gaan naar Thousand Needles. We kwamen hier om de verschillende wezens te bestuderen die in deze mooie landen leven.$B$BIk waardeer de hulp die je Pao'ka hebt gegeven. Ik hoop dat dit alle pech goedmaakt die deze daad je heeft gekost.",
  e = "Begeleid Pao'ka uit Highperch",
  g = { {"verstop me", "hide (zich verstoppen)"}, {"bestuderen", "study"}, {"weggejaagd", "chased away (wegjagen)"}, {"nesten", "nests (nest)"}, {"verdwaald", "lost (verdwalen)"}, {"vermist", "missing"}, {"woedend", "furious"}, {"in mijn eentje", "by myself"}, {"Begeleid", "escort (begeleiden)"}, {"rondneuzen", "snoop around"}, {"vastgeketend", "chained (vastketenen)"}, {"waardeer", "appreciate (waarderen)"}, {"pech", "bad luck, misfortune"}, {"goedmaakt", "makes up for (goedmaken)"} },
},

[4904] = { en = "Free at Last", tier = 2,
  t = "Eindelijk vrij",
  d = "Arnak denkt dat we gaan trouwen... maar nadat ik zijn aanzoek had afgewezen, kwam hij die nacht terug en ontvoerde hij me. Mijn broer probeerde hem tegen te houden, maar Arnak was te sterk. Hij... hij doodde mijn broer en bracht mij toen hierheen. Mijn arme broer...$B$B$N, wil je me uit Darkcloud Pinnacle begeleiden? Alsjeblieft... ik moet terug naar Thalia! Ze maakt zich vast vreselijk zorgen om me.",
  o = "Begeleid Lakota Windsong uit Darkcloud Pinnacle en praat daarna met Thalia Amberhide in Freewind Post.",
  p = "Thalia Amberhide:",
  c = "Dank je, $N. Diep vanbinnen wist ik dat ze de weg naar mij terug zou vinden. Ze heeft me verteld hoe dapper je was en hoe je haar hielp ontsnappen. Deze spullen waren van haar broer. Ik weet dat ze wil dat jij ze krijgt.",
  e = "Begeleid Lakota Windsong uit Darkcloud Pinnacle.",
  g = { {"trouwen", "marry"}, {"aanzoek", "proposal (of marriage)"}, {"afgewezen", "declined, rejected (afwijzen)"}, {"ontvoerde", "kidnapped (ontvoeren)"}, {"tegen te houden", "stop (tegenhouden)"}, {"doodde", "killed, slew (doden)"}, {"maakt zich zorgen", "is worried (zich zorgen maken)"}, {"vreselijk", "terribly"}, {"Diep vanbinnen", "deep inside, deep in my bones"}, {"ontsnappen", "escape"}, {"spullen", "things, items"} },
},

[5147] = { en = "Wanted - Arnak Grimtotem", tier = 2,
  t = "Gezocht - Arnak Grimtotem",
  d = "Gezocht: Arnak Grimtotem$B$BArnak de verstotene wordt gezocht voor de gruwelijke misdaden moord en ontvoering. Wie dapper genoeg is om deze misdadiger voor het gerecht te brengen, krijgt een flinke beloning.$B$BArnak is voor het laatst gezien op de kliffen bij Darkcloud Pinnacle. Laat het bewijs van je daad zien aan Cliffwatcher Longhorn in Freewind Post om de beloning op te halen.",
  o = "Dood Arnak Grimtotem en breng het bewijs van je daad naar Cliffwatcher Longhorn in Freewind Post.",
  p = "Heb je nieuws over die moordenaar Arnak Grimtotem?",
  c = "Ha! Nou, dit is uitstekend nieuws! Ik begon al te denken dat hij nooit voor het gerecht zou komen!$B$BAlsjeblieft, $N... en bedankt. Van het nieuws over Arnaks gemene daden kookte mijn bloed!",
  g = { {"Gezocht", "wanted (zoeken)"}, {"verstotene", "outcast"}, {"gruwelijke", "heinous, horrible (gruwelijk)"}, {"misdaden", "crimes (misdaad)"}, {"moord", "murder"}, {"ontvoering", "kidnapping"}, {"misdadiger", "criminal"}, {"voor het gerecht te brengen", "bring to justice"}, {"flinke", "handsome, sizeable (flink)"}, {"kliffen", "cliffs (klif)"}, {"op te halen", "collect, claim (ophalen)"}, {"uitstekend", "excellent"}, {"kookte mijn bloed", "boiled my blood (koken)"} },
},

[1150] = { en = "Test of Endurance", tier = 2,
  t = "Proef van uithoudingsvermogen",
  d = "Ik ben blij dat je moed nog steeds sterk is, na alles wat je al hebt gedaan. Omdat je geloof heel is gebleven, is het tijd om je lichaam te testen.$B$BEerst komt een proef van uithoudingsvermogen. Ga met vrienden naar de Roguefeather Den, ten westen van Freewind Post. Ga naar het diepste deel van hun hol en vernietig hun voedselvoorraad. Daarmee heb je hun woede opgewekt, en als je lang genoeg kunt overleven, komt Grenka Bloodscreech zelf op je af. Dood haar en breng me haar klauw om je proef af te maken.",
  o = "Breng Grenka's Claw naar Dorn Plainstalker in Thousand Needles.",
  p = "Je moet geestelijk, lichamelijk en mentaal voorbereid zijn op de uitdagingen die voor je liggen.$B$BTe vaak rennen we vooruit voordat we klaar zijn. Ik zie het als mijn plicht tegenover de jeugd, van welke stam ze ook zijn, om ze voor te bereiden op de gevaren die ze kunnen tegenkomen als ze de heiligheid van hun thuis verlaten.",
  c = "Grenka was sterk, zelfs voor een trol. Je mag vandaag trots zijn op wat je hebt bereikt.$b$bTijdens je proef van geloof liet je de kracht van je geest zien, en nu heb je uithoudingsvermogen in de strijd getoond door de Roguefeather harpijen aan te pakken. Maar het is tijd voor een nieuwe proef.",
  g = { {"uithoudingsvermogen", "endurance, stamina"}, {"moed", "courage"}, {"heel is gebleven", "has stayed intact"}, {"diepste", "deepest (diep)"}, {"hol", "den, lair"}, {"vernietig", "destroy (vernietigen)"}, {"voedselvoorraad", "food supply, foodstuffs"}, {"opgewekt", "provoked, roused (opwekken)"}, {"klauw", "claw"}, {"geestelijk", "spiritually"}, {"lichamelijk", "physically"}, {"uitdagingen", "challenges (uitdaging)"}, {"plicht", "duty"}, {"stam", "tribe"}, {"heiligheid", "sanctity"}, {"harpijen", "harpies (harpij)"} },
},

[1151] = { en = "Test of Strength", tier = 2,
  t = "Proef van kracht",
  d = "In de tijd van de Old Gods leefden er elementalen op een groot deel van deze wereld. Ze aanbaden de Old Gods, en de goden hielden de elementalen met hun macht aan deze wereld gebonden. Toen de Old Gods werden verbannen, verdwenen de elementalen uit onze wereld. Nu komen ze alleen nog terug als machtige magiërs ze oproepen.$B$BEr zijn wel uitzonderingen. Sommige elementalen waren sterk genoeg om hier uit zichzelf te blijven. Een van die elementalen is Rok'Alim.$B$BOm je kracht te testen moet je Rok'Alim in Thousand Needles vinden en hem doden.",
  o = "Breng Fragments of Rok'Alim naar Dorn Plainstalker in Thousand Needles.",
  p = "De centaurstammen in Thousand Needles noemen Rok'Alim ook de Pounder, vanwege het gedonder van zijn vuisten als hij de wezens in elkaar slaat die dapper, of dom, genoeg zijn om hem in de weg te staan.",
  c = "De Proef van kracht is voorbij. Je hebt kracht en moed laten zien, en je bent nu klaar voor de laatste proef voordat deze rituelen voltooid zijn.",
  g = { {"aanbaden", "worshipped (aanbidden)"}, {"gebonden", "bound (binden)"}, {"verbannen", "banished"}, {"verdwenen", "faded, disappeared (verdwijnen)"}, {"magiërs", "mages (magiër)"}, {"uitzonderingen", "exceptions (uitzondering)"}, {"uit zichzelf", "on their own"}, {"centaurstammen", "centaur tribes"}, {"gedonder", "thundering"}, {"vuisten", "fists (vuist)"}, {"in elkaar slaat", "beats up, pummels (in elkaar slaan)"}, {"in de weg te staan", "stand in the way"}, {"rituelen", "rites, rituals (ritueel)"}, {"voltooid", "completed (voltooien)"} },
},

[1152] = { en = "Test of Lore", tier = 2,
  t = "Proef van kennis",
  d = "Je tijd bij mij is bijna voorbij. Ik weet veel, maar de Proef van kennis is niet aan mij om te geven. Er zijn lessen te leren en plaatsen te bezoeken waar anderen over heersen.$B$BAls je klaar bent, zoek dan Braug Dimspirit op. Hij is een sjamaan met grote wijsheid. Hij zal je verder testen, dus luister goed naar zijn woorden, $N.$B$BAls je zover bent, zoek dan de tunnel tussen de Stonetalon Mountains en Ashenvale: Braug woont daar in de buurt. En wees voorzichtig, $N, de nachtelfen willen je proef misschien tegenhouden.",
  o = "Zoek Braug Dimspirit bij de ingang van Talondeep Path in Stonetalon Mountains.",
  c = "De dagen en nachten worden overal in de wereld kouder, terwijl goblins het land misbruiken en de nachtelfen met de vinger wijzen naar de jongere volken. De Forsaken en de orks zijn niet de enigen die schuld hebben aan de ellende in Kalimdor en Lordaeron. Veel van de intelligente volken hebben bijgedragen aan de pijn van de wereld. Dorn weet dit, en hij heeft je naar mij gestuurd omdat je de eigenschappen hebt laten zien die nodig zijn om dit ook te beseffen.$b$bNu sta je voor Braug.",
  g = { {"kennis", "knowledge, lore"}, {"heersen", "rule, claim domain"}, {"wijsheid", "wisdom"}, {"Als je zover bent", "when you're ready"}, {"nachtelfen", "night elves (nachtelf)"}, {"ingang", "entrance"}, {"misbruiken", "abuse, ravage"}, {"met de vinger wijzen naar", "point fingers at"}, {"volken", "races, peoples (volk)"}, {"schuld", "blame"}, {"ellende", "hardship, misery"}, {"bijgedragen", "contributed (bijdragen)"}, {"eigenschappen", "attributes, qualities (eigenschap)"}, {"beseffen", "realize"} },
},

[1154] = { en = "Test of Lore", tier = 2,
  t = "Proef van kennis",
  d = "Je bent geslaagd voor de proeven van Dorn, en nu wil je slagen voor je volgende beproeving. Heel goed. Maar tot nu toe waren je uitdagingen kinderachtig. Het is makkelijk om je lichaam te testen - je verstand is iets heel anders.$B$BIk zal het eenvoudig uitleggen: zoek het boek dat ik noem, bestudeer het, en beantwoord mijn vraag over wat erin staat.$B$BWelk boek, vraag je je vast af? The Legacy of the Aspects. Je vindt het helemaal onderin Dor'danil, in het zuiden van Ashenvale. Het wordt beschermd door de dode druïden en hun moordenaars.",
  o = "Zoek het boek Legacy of the Aspects en breng het terug naar Braug Dimspirit bij de ingang van Talondeep Path in Stonetalon Mountains.",
  p = "Breng me het boek als je het hebt bestudeerd. Ik stel je mijn vraag pas als je me het boek hebt gegeven.",
  c = "Dit is het boek dat ik noemde. Er is dus hoop dat je mijn vraag goed beantwoordt... tenzij je bent vergeten te bestuderen wat erin staat.$b$bAls je klaar bent, praat dan weer met me, en dan stel ik je een vraag.",
  g = { {"geslaagd", "passed (slagen)"}, {"beproeving", "trial, ordeal"}, {"kinderachtig", "childish"}, {"iets heel anders", "another matter completely"}, {"eenvoudig", "simply"}, {"bestudeer", "study (bestuderen)"}, {"beantwoord", "answer (beantwoorden)"}, {"wat erin staat", "its contents"}, {"helemaal onderin", "at the very bottom"}, {"druïden", "druids (druïde)"}, {"tenzij", "unless"} },
},

[1159] = { en = "Test of Lore", tier = 2,
  t = "Proef van kennis",
  d = "Goed gedaan, $N. Je bent geslaagd voor het eerste deel van de Proef van kennis, maar er moet nog een vraag beantwoord worden. Maar die vraag is niet aan mij om te stellen.$B$BZoek Parqual Fintallas in Lordaeron City. Hij was een groot geschiedkundige voor de mensen, voordat de pest hem overmande. Nu zoekt hij nog steeds verlichting, maar van een andere soort.$B$BHij heeft nog iets anders van je nodig voordat hij je iets vraagt, maar je hebt het tot nu toe meesterlijk gedaan - ik weet zeker dat je zijn hindernis zult overwinnen.",
  o = "Zoek Parqual Fintallas in Undercity.",
  c = "Heeft Braug je gestuurd? Onmogelijk.$b$b<Parqual bekijkt je van top tot teen.>$b$bJe hebt Dor'Danil getrotseerd, een sprong in het diepe gewaagd, en een machtige elementaal bevochten en verslagen? Bah! Je bent vast een bedrieger; een avonturier die in een herberg iemand iets heeft horen vertellen. En nu denk je dat je genoeg in je hebt om voor mijn proef te slagen. Het zij zo... $C.",
  g = { {"deel", "portion, part"}, {"geschiedkundige", "historian"}, {"de pest", "the Plague"}, {"overmande", "overtook, overpowered (overmannen)"}, {"verlichting", "enlightenment"}, {"meesterlijk", "masterfully"}, {"hindernis", "obstacle"}, {"overwinnen", "overcome"}, {"van top tot teen", "from head to toe, up and down"}, {"getrotseerd", "braved, defied (trotseren)"}, {"bevochten", "fought (bevechten)"}, {"bedrieger", "fraud, impostor"}, {"herberg", "tavern, inn"}, {"genoeg in je hebt", "have what it takes"}, {"Het zij zo", "so be it"} },
},

[5151] = { en = "Hypercapacitor Gizmo", tier = 2,
  t = "De Hypercapacitor Gizmo",
  d = "Ik ben de enige overlevende van onze karavaan, die door de centauren werd aangevallen! Een zeldzame maar machtige panter bewaakt mijn beste apparaatje, dat om zijn nek hangt. Ha! Zelfs de centauren beven als dit woeste beest in de buurt is!$B$BHier is de sleutel van de kooi. Ze hebben daar alles meegenomen, maar hem lieten ze met rust. Dood dit beest en breng mijn hypercapacitor terug, dan beloon ik je.$b$bDe kapotte karavaan staat net ten noorden van hier.$b",
  o = "Dood het beest en breng de Hypercapacitor Gizmo en de Panther Cage Key terug naar Wizlo Bearingshiner.",
  p = "Heb je mijn hypercapacitor?",
  c = "Mijn hypercapacitor! Hiermee ben ik wel even bezig, tot ik uitvind wat hij doet...",
  g = { {"overlevende", "survivor"}, {"karavaan", "caravan"}, {"panter", "panther"}, {"apparaatje", "gizmo, little device (apparaat)"}, {"nek", "neck"}, {"beven", "tremble"}, {"woeste", "ferocious, wild (woest)"}, {"kooi", "cage"}, {"met rust", "alone (met rust laten)"}, {"kapotte", "wrecked, broken (kapot)"}, {"uitvind", "figure out (uitvinden)"} },
},

[6627] = { en = "Test of Lore", tier = 2,
  t = "Proef van kennis",
  d = "Je hebt me het boek gebracht, en nu is het tijd voor je vraag. Ben je er klaar voor?$B$BTijd speelt geen rol, $c, dus voel je niet onder druk gezet. Je mag er zo lang over doen als je wilt.",
  o = "Beantwoord de vraag van Braug Dimspirit goed en praat daarna weer met hem. Hij blijft in Stonetalon Mountains tot je klaar bent.",
  p = "Het leven zit vol vragen, $C. Je zult ze nooit allemaal kunnen beantwoorden, maar met wat tijd en studie krijg je misschien een beetje meer kennis.",
  c = "Goed gedaan, $C. Je hebt de tekst bestudeerd die ik je had opgegeven, en nu ben je geslaagd voor nog een van onze proeven.",
  e = "Beantwoord de vraag van Braug Dimspirit goed",
  g = { {"speelt geen rol", "is not an issue (een rol spelen)"}, {"onder druk gezet", "pressured (onder druk zetten)"}, {"er zo lang over doen", "take as long (ergens lang over doen)"}, {"zit vol", "is full of (vol zitten)"}, {"studie", "study"}, {"opgegeven", "assigned (opgeven)"} },
},

[6628] = { en = "Test of Lore", tier = 2,
  t = "Proef van kennis",
  d = "Dus de tijd is weer aangebroken. Als student van de overlevering heb je veel doorzettingsvermogen getoond door mijn opdracht aan te nemen.$B$BEn dus geef ik je nu je vraag. Als je klaar bent, praat dan weer met me, en neem alle tijd die je nodig hebt, $N - je hoeft niet snel te antwoorden.",
  o = "Beantwoord de vraag van Parqual Fintallas goed en praat daarna weer met hem. Hij blijft in Undercity tot je klaar bent.",
  p = "Er is maar één regel die je volgens mij moet kennen als je wilt overleven in deze wereld: hoe meer je weet, hoe meer je ziet.$b$bAls je studeert, als je goed kijkt, dan ga je dingen in de wereld zien die geen enkele andere $r ziet.",
  c = "Goed gedaan, $N. Ik twijfelde of je de tekst had bestudeerd die je van mij moest halen, maar je hebt het goede antwoord gegeven.",
  e = "Beantwoord de vraag van Parqual Fintallas goed",
  g = { {"aangebroken", "arrived, come (aanbreken)"}, {"overlevering", "lore"}, {"doorzettingsvermogen", "tenacity, perseverance"}, {"getoond", "shown (tonen)"}, {"aan te nemen", "take on, accept (aannemen)"}, {"regel", "rule"}, {"overleven", "survive"}, {"hoe meer ... hoe meer", "the more ... the more"}, {"geen enkele", "not a single, no"}, {"twijfelde", "doubted (twijfelen)"} },
},

[1147] = { en = "The Swarm Grows", tier = 2,
  t = "De zwerm groeit",
  d = "Hm. Belgrom denkt blijkbaar dat die monsters een gevaar zijn. Hij wil dat ze teruggedreven worden naar de diepte waar ze uit omhoog zijn gekropen.$B$BHet was blijkbaar niet genoeg om de dwergen te doden die de Explorers' League had gestuurd - nu moet ik een half dode strijdgroep naar een nieuwe veldslag sturen. Zelf kunnen we het niet; niet in deze toestand. De opgraving ligt ten zuiden van hier. Er zouden geen dwergen meer moeten zijn om af te handelen. Heb je zin om een kling of een staf te hanteren en je deel te doen om ons te helpen?",
  o = "Dood 5 Silithid Searchers, 5 Silithid Hive Drones en 5 Silithid Invaders en ga terug naar Moktar Krin in Thousand Needles.",
  p = "Met al die reizigers die voor de races naar de Flats gaan, kunnen we vast genoeg avonturiers overhalen om die insecten terug te drijven. Mijn groep en ik kunnen pas vertrekken als dat gelukt is.",
  c = "Ha! Door dat ichor waar je onder zit, zie je er zelfs mooier uit, $N! Maar je stinkt er ook flink door. Ga niet te dicht bij de kodo's staan; dan slaan ze op hol of worden ze bronstig.$B$BIk denk dat mijn kameraden het met me eens zijn dat je geur alleen al bewijst dat je je deel hebt gedaan om ons te helpen tegen die insecten. Bedankt, $N.$b",
  g = { {"zwerm", "swarm"}, {"blijkbaar", "apparently"}, {"teruggedreven", "pushed back (terugdrijven)"}, {"gekropen", "crawled (kruipen)"}, {"strijdgroep", "war party"}, {"veldslag", "battle"}, {"toestand", "condition, state"}, {"opgraving", "dig site"}, {"af te handelen", "deal with (afhandelen)"}, {"kling", "blade"}, {"hanteren", "wield, handle"}, {"overhalen", "persuade, convince"}, {"ichor", "ichor (insect blood)"}, {"stinkt", "reek, stink (stinken)"}, {"slaan ze op hol", "they stampede (op hol slaan)"}, {"bronstig", "in heat"}, {"kameraden", "companions (kameraad)"} },
},

[1148] = { en = "Parts of the Swarm", tier = 2,
  t = "Delen van de zwerm",
  d = "Je bekijkt het pantser zorgvuldig. Terwijl je het in je handen omdraait, zie je dat de platen van chitine zo in elkaar grijpen dat het ongelooflijk sterk is. Het lijkt op niets wat je ooit hebt gezien. Je bekijkt de rest van het lijk nog beter en beseft dat deze wezens heel machtig en ver ontwikkeld zijn.$B$BAls je weer naar het pantser kijkt, denk je dat Korran het leuk zou vinden om meer van deze wezens te bestuderen. Het kan hem helpen uit te vinden wat deze wezens zijn en waar ze vandaan komen.",
  o = "Breng 1 Silithid Heart, 5 Silithid Talons en 3 Intact Silithid Carapaces naar Korran in de Crossroads.",
  p = "Ah, het is lang geleden dat je bij me op bezoek kwam, $N. Wat kan ik vandaag voor je doen? Je ziet eruit alsof je pas nog de strijd hebt gezien. Goed... goed voor de Horde en goed voor jou. Hoe meer strijd je hebt gezien, hoe nuttiger je zult zijn; en sterker ook.",
  c = "Ahh, heb je Moktar onlangs gezien? Hij let altijd op mij. Het spijt me te horen dat hij zijn tijd besteedt aan het bewaken van zijn kleine strijdgroep in plaats van te vechten, maar ik weet zeker dat hij veel plezier heeft in het doden van leden van de Explorers' League.$B$BHet is slim van je dat je me deze exemplaren brengt, $N. Samen met de eieren die we in het Field of Giants vinden, moeten deze me een goede start geven om uit te vinden wat deze insecten zijn, en wat ze willen.",
  g = { {"pantser", "carapace, armour"}, {"zorgvuldig", "carefully"}, {"omdraait", "turn over (omdraaien)"}, {"platen", "plates (plaat)"}, {"chitine", "chitin"}, {"in elkaar grijpen", "interlock (in elkaar grijpen)"}, {"ongelooflijk", "incredibly"}, {"lijk", "corpse"}, {"ver ontwikkeld", "highly evolved"}, {"nuttiger", "more useful (nuttig)"}, {"onlangs", "recently"}, {"let op", "looks out for (letten op)"}, {"besteedt", "spends (besteden)"}, {"bewaken", "watch over, guard"}, {"exemplaren", "specimens (exemplaar)"} },
},

[1184] = { en = "Parts of the Swarm", tier = 2,
  t = "Delen van de zwerm",
  d = "Ga terug naar Belgrom in Orgrimmar en zeg hem dat Moktar zijn bevelen goed uitvoert in Thousand Needles. Zeg hem ook dat mijn onderzoek vordert, en dat ik hoop snel meer te weten. Daar zal hij erg blij mee zijn.",
  o = "Ga terug naar Belgrom Rockmaul in Orgrimmar.",
  c = "Ik waardeer je inspanningen, $c. De krijgsheer zal graag horen hoe vasthoudend je je taken hebt gedaan.$B$BO, natuurlijk zal ik je naam bij hem noemen. Hij praat vaak met me en hecht veel waarde aan mijn mening.$B$BGa nu, ik heb veel te doen. En als je Korran binnenkort spreekt en hij nieuws heeft over deze wezens, kom dan terug bij mij - ik denk dat ze een gevaar zijn dat we serieus moeten nemen.",
  g = { {"bevelen", "orders, bidding (bevel)"}, {"uitvoert", "carries out (uitvoeren)"}, {"onderzoek", "research, studies"}, {"vordert", "progresses (vorderen)"}, {"inspanningen", "efforts (inspanning)"}, {"krijgsheer", "warchief, warlord"}, {"vasthoudend", "tenacious"}, {"taken", "duties, tasks (taak)"}, {"hecht veel waarde aan", "values greatly (waarde hechten aan)"}, {"mening", "opinion"}, {"serieus", "seriously"} },
},

[5361] = { en = "Family Tree", tier = 2,
  t = "Stamboom",
  d = "Mijn broer Nataka is gestationeerd in Ghost Walker Post, in Desolace. Ik wil je iets vragen... wil je dit verslag voor mij aan hem geven? Er is een jaar voorbij sinds ik hem voor het laatst schreef. Sindsdien doen de centauren ongewone dingen, en hij moet dat weten.$B$BReis naar de Stonetalon Mountains, ten noorden van de Crossroads, en ga dan naar het westen, de Charred Vale in. Ga vandaar naar het zuiden, naar Desolace; daar vind je een weg die naar het zuiden gaat, naar Ghost Walker Post.",
  o = "Breng het Cliffwatcher Longhorn Report naar Nataka Longhorn in Ghost Walker Post in Desolace.",
  p = "Wat voor nieuws heb je, $c! Ah - een bericht van mijn broer, zeg je? Nou, geef dat verslag dan maar hier!",
  c = "Ik weet niet wat jij met mijn broer te maken hebt, maar het lijkt erop dat hij je vertrouwt, $C.$B$BIk ben Nataka Longhorn en ik heet je welkom in Ghost Walker Post. We hebben veel nodig van een $C! Praat met de anderen, misschien hebben ze je hier nodig.",
  g = { {"Stamboom", "family tree"}, {"gestationeerd", "stationed"}, {"verslag", "report"}, {"sinds", "since"}, {"Sindsdien", "since then"}, {"ongewone", "unusual (ongewoon)"}, {"vandaar", "from there"}, {"te maken hebt met", "have to do with (te maken hebben met)"}, {"vertrouwt", "trusts (vertrouwen)"}, {"heet je welkom", "welcome you (welkom heten)"} },
},

[1394] = { en = "Final Passage", tier = 3,
  t = "De laatste overgang",
  d = "Je hebt het goed gedaan, $N. Je bent geslaagd voor mijn proef, en voor de proeven daarvoor. Ga terug naar Dorn in Thousand Needles. Hij zal de verandering in je voelen, en zien dat je verstand, lichaam en geest sterk genoeg zijn om beloond te worden voor je moeite.$B$BBlijf trouw aan het evenwicht dat je tijdens deze beproevingen hebt laten zien, $N. Als je dat doet, zal Dorn je in de toekomst opnieuw op de proef stellen.",
  o = "Praat met Dorn Plainstalker in Thousand Needles.",
  c = "Ah, $N. Het is lang geleden dat je voor het laatst mijn huis binnenstapte. Het lijkt alsof er vele manen voorbij zijn gegaan sinds je de eerste sprong maakte die je op je pad zette.$b$bEn nu keer je terug, sterker dan je eerst was... meer verlicht. Dit doet me plezier. En je verdient een eerlijke beloning, omdat je mijn proeven tot het einde hebt doorlopen.",
  g = { {"overgang", "passage, transition"}, {"verandering", "change"}, {"beloond", "rewarded (belonen)"}, {"moeite", "effort"}, {"trouw", "true, loyal"}, {"evenwicht", "balance"}, {"beproevingen", "trials (beproeving)"}, {"op de proef stellen", "put to the test"}, {"binnenstapte", "stepped into (binnenstappen)"}, {"manen", "moons (maan)"}, {"keer terug", "return (terugkeren)"}, {"verlicht", "enlightened"}, {"doet me plezier", "pleases me"}, {"verdient", "deserve (verdienen)"}, {"doorlopen", "gone through, completed"} },
},

})

